 const route=fn=>async(req,res,next)=>{try{await fn(req,res);}catch(e){if(res.headersSent)return next(e);res.status(e.status||500).json({error:e.status?e.message:'The request could not be completed. Please try again.',...(e.type?{type:e.type,conflicts:e.conflicts||[]}: {})});if(!e.status)console.error('[business]',e.message);}};
 app.use((req,res,next)=>{if(process.env.COMMERCE_PAUSED==='true'&&req.method==='POST'&&['/checkout','/custom-requests','/projects/current/pay'].includes(req.path))return res.status(503).json({error:'Ordering is temporarily unavailable while we finish preparing the store. Please check back shortly.'});next();});
